import{_ as o,l as n,o as e,c as i,v as t,p as s,x as r,d as E,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"权证与雇员期权","description":"","frontmatter":{"title":"权证与雇员期权","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/warrants-eso.md","filePath":"quant/warrants-eso.md","lastUpdated":1789023840000}'),p={name:"quant/warrants-eso.md"};function u(c,a,B,A,m,_){const l=n("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="权证与雇员期权" tabindex="-1">权证与雇员期权 <a class="header-anchor" href="#权证与雇员期权" aria-label="Permalink to &quot;权证与雇员期权&quot;">​</a></h1><div class="epigraph"><p>雇员期权不可转让、可能作废、且持有人不能对冲；用上市香草的 BSM 去估费用，会把不可交易的限制当成波动率折减。</p><footer>—— Hull and White, How to Value Employee Stock Options, Financial Analysts Journal, 2004</footer></div><p><a href="/quant/option-strategies">上一课</a>的组合默认腿可交易、可对冲。权证与雇员股票期权（ESO）的缺口是<strong>合约与持有人约束</strong>：公司发行稀释、雇员不可卖出、离职作废、以及权证的稀释与做市。主干 <a href="/quant/american-exercise">美式期权</a> 已写提前行权；本课只补这些市场微结构与会计估值里多出来的状态，不重写美式树。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>上市权证常是公司或券商发行的美式看涨，条款含稀释、赎回、停牌。ESO 更极端：等待期（vesting）、离职后短暂可行权窗口、不可转让，持有人往往过早行权。问题是定价核：市场香草假设对冲与可转让，ESO 的「公平费用」若仍用同一 <a href="/quant/bsm">BSM</a> 隐波，等于忽略作废率与过早行权，通常<strong>高估</strong>费用。Hull–White（2004）把退出率与行权倍数（现价相对执行价的门槛）写进树，对象是费用计量，不是给雇员一个可对冲的交易价格。</p><p>稀释：权证行权时公司发新股，标的从 \\(S\\) 变成对资产池的摊薄要求权。Galai–Schneller 把权证写成公司价值上的期权，而不是对已上市股票的普通期权。把权证当「股票看涨」会在发行量大时系统性偏贵。</p><h3 id="过早行权不是「美式比欧式贵」那句话" tabindex="-1">过早行权不是「美式比欧式贵」那句话 <a class="header-anchor" href="#过早行权不是「美式比欧式贵」那句话" aria-label="Permalink to &quot;过早行权不是「美式比欧式贵」那句话&quot;">​</a></h3><p>美式看涨在无分红下不应提前行权；ESO 持有人为了分散、流动与税，会在价内不深时就行权。这是效用与约束，不是无套利。模型里用外生的行权强度或门槛倍数去拟合历史行权行为，会把行为风险当成波动率。会计上可接受，交易上不能用这个「折减 vol」去对冲上市权证。</p><p><span class="marginnote">覆盖性认购（covered warrant）由券商发行、用对冲簿复制，更接近普通权证；公司认股权证才有稀释。两者不要共用 Galai 公式。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>公司权证：在公司资产或稀释后股权上建树，行权时增加股份数，支付用摊薄后价格。上市覆盖权证：按条款当美式/欧式香草，用与上市期权一致的曲面，注意报价货币与除权。ESO：Hull–White 树或等价的强度模型，输入预期退出率、行权倍数、等待期；费用在授予日按不可转让约束计算，后续按会计规则摊销——那是账，不是盯市。</p><p>对冲上市权证用香草与期货；对冲 ESO 费用不是交易台的复制问题，公司若买回股份是资本结构决策。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>不可转让切断了持有人把期权卖给能更好对冲的人，于是提前行权被拿来当流动性工具。作废是一个跳跃：离职强度把存活概率从定价核里乘掉。稀释把标的从「每股」改成「对资产的份额」，行权同时改变份额。三者都不是新的随机波动，而是合约状态。</p>',14)),(e(),s(h,null,{default:r(()=>[d(l,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20CW%5B%22%E8%A6%86%E7%9B%96%E6%9D%83%E8%AF%81%20%E5%8F%AF%E5%AF%B9%E5%86%B2%22%5D%20--%3E%20Surf%5B%22%E7%94%A8%E4%B8%8A%E5%B8%82%E6%9B%B2%E9%9D%A2%22%5D%0A%20%20CoW%5B%22%E5%85%AC%E5%8F%B8%E6%9D%83%E8%AF%81%22%5D%20--%3E%20Dil%5B%22%E7%A8%80%E9%87%8A%E5%90%8E%E7%9A%84%E8%B5%84%E4%BA%A7%E6%9C%9F%E6%9D%83%22%5D%0A%20%20ESO%5B%22%E9%9B%87%E5%91%98%E6%9C%9F%E6%9D%83%22%5D%20--%3E%20Vest%5B%22%E7%AD%89%E5%BE%85%20%E4%BD%9C%E5%BA%9F%20%E8%BF%87%E6%97%A9%E8%A1%8C%E6%9D%83%22%5D%0A%20%20Vest%20--%3E%20HW%5B%22Hull-White%20%E6%A0%91%E4%BC%B0%E8%B4%B9%E7%94%A8%22%5D%0A%20%20Dil%20--%3E%20Tree%5B%22%E6%A0%91%E6%88%96%20PDE%20%E5%B8%A6%E8%82%A1%E4%BB%BD%E6%95%B0%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>退出率与行权倍数不稳定，危机年与牛市年差一截；用历史均值估当年授予费用会偏。税务（ISO/NSO、境内个人所得税时点）改变最优行权，模型若不含税就不是雇员的真实问题。权证做市还受涨跌停与流动性，希腊值在停牌时无法对冲。</p><p>本课不写如何设计期权池去规避激励会计。对象是估值约束与稀释。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>覆盖权证接近可对冲香草；公司权证要稀释；ESO 要作废与过早行权。</li><li>用上市 BSM 隐波估 ESO 费用通常偏高；Hull–White 把行为写进树。</li><li>行为折减不能拿去对冲可交易权证。</li><li>出处：Hull and White, <em>FAJ</em>, 2004；Galai and Schneller, <em>Journal of Finance</em>, 1978。</li></ul>',5))])}const D=o(p,[["render",u]]);export{f as __pageData,D as default};
